DECLARE @duckImgTable TABLE (idx INT IDENTITY(1,1), img varbinary(max));
INSERT INTO @duckImgTable VALUES (@mallard_duck01);
INSERT INTO @duckImgTable VALUES (@mallard_duck02);
INSERT INTO @duckImgTable VALUES (@mallard_duck03);
INSERT INTO @duckImgTable VALUES (@mallard_duck04);
INSERT INTO @duckImgTable VALUES (@mallard_duck05);
INSERT INTO @duckImgTable VALUES (@mallard_duck06);
INSERT INTO @duckImgTable VALUES (@mallard_duck07);
INSERT INTO @duckImgTable VALUES (@mallard_duck08);
INSERT INTO @duckImgTable VALUES (@mallard_duck09);
INSERT INTO @duckImgTable VALUES (@mallard_duck10);
INSERT INTO @duckImgTable VALUES (@mallard_duck11);
INSERT INTO @duckImgTable VALUES (@mallard_duck12);

DECLARE @duck_i INT = 13;
WHILE @duck_i <= 55
BEGIN
    DECLARE @duckUser VARCHAR(450) =
        CASE ((@duck_i - 1) % 5)
            WHEN 0 THEN 'df6405d9-0dfb-415d-b77b-c779cecd000c'
            WHEN 1 THEN '74e0f665-41e5-42dc-9681-0501f6eb392a'
            WHEN 2 THEN '2b8804ff-37bd-41e5-868e-034a810f968c'
            WHEN 3 THEN 'e98cdd8d-ca1f-4492-8090-266657903f23'
            ELSE        '0383420e-1d8a-4481-93b4-febe2978ec92'
        END;
    DECLARE @duckImg  varbinary(max) = (SELECT img FROM @duckImgTable WHERE idx = ((@duck_i - 1) % 12) + 1);
    DECLARE @duckLat  DECIMAL(9,6) = CAST(44.0 + ((@duck_i % 20) * 0.05)  AS DECIMAL(9,6));
    DECLARE @duckLong DECIMAL(9,6) = CAST(-122.0 - ((@duck_i % 15) * 0.04) AS DECIMAL(9,6));
    IF NOT EXISTS (
        SELECT 1 FROM [dbo].[Sighting]
        WHERE  SpeciesName = N'Mallard Duck'
        AND    Description = CONCAT(N'Mallard duck sighting #', @duck_i, N' at an Oregon waterway.')
    )
    INSERT INTO [dbo].[Sighting]
        (Id, UserId, Lat, [Long], Timestamp, Description, SpeciesName, ImageBuffer,
         PointValue, LoginStreak, Rarity, RarityMultiplier,
         QualityTier, SharpnessScore, LuminanceAverage, ResolutionWidth, ResolutionHeight,
         FlaggedForReview, ClientSightingId)
    VALUES (NEWID(), @duckUser, @duckLat, @duckLong,
            DATEADD(day, -(@duck_i * 3), GETUTCDATE()),
            CONCAT(N'Mallard duck sighting #', @duck_i, N' at an Oregon waterway.'),
            N'Mallard Duck', @duckImg, 10, 0, N'Common', 1.0, 2, NULL, NULL, NULL, NULL, 0, NULL);
    SET @duck_i = @duck_i + 1;
END;

