DECLARE @sq_i INT = 13;
WHILE @sq_i <= 52
BEGIN
    DECLARE @sqUser VARCHAR(450) =
        CASE ((@sq_i - 1) % 5)
            WHEN 0 THEN 'df6405d9-0dfb-415d-b77b-c779cecd000c'
            WHEN 1 THEN '74e0f665-41e5-42dc-9681-0501f6eb392a'
            WHEN 2 THEN '2b8804ff-37bd-41e5-868e-034a810f968c'
            WHEN 3 THEN 'e98cdd8d-ca1f-4492-8090-266657903f23'
            ELSE        '0383420e-1d8a-4481-93b4-febe2978ec92'
        END;
    DECLARE @sqImg  varbinary(max) = (SELECT img FROM @sqImgTable WHERE idx = ((@sq_i - 1) % 12) + 1);
    DECLARE @sqLat  DECIMAL(9,6) = CAST(44.5 + ((@sq_i % 18) * 0.04) AS DECIMAL(9,6));
    DECLARE @sqLong DECIMAL(9,6) = CAST(-122.5 - ((@sq_i % 12) * 0.05) AS DECIMAL(9,6));
    IF NOT EXISTS (
        SELECT 1 FROM [dbo].[Sighting]
        WHERE  SpeciesName = N'Eastern Gray Squirrel'
        AND    Description = CONCAT(N'Eastern gray squirrel sighting #', @sq_i, N' in an Oregon park or urban greenspace.')
    )
    INSERT INTO [dbo].[Sighting]
        (Id, UserId, Lat, [Long], Timestamp, Description, SpeciesName, ImageBuffer,
         PointValue, LoginStreak, Rarity, RarityMultiplier,
         QualityTier, SharpnessScore, LuminanceAverage, ResolutionWidth, ResolutionHeight,
         FlaggedForReview, ClientSightingId)
    VALUES (NEWID(), @sqUser, @sqLat, @sqLong,
            DATEADD(day, -(@sq_i * 2), GETUTCDATE()),
            CONCAT(N'Eastern gray squirrel sighting #', @sq_i, N' in an Oregon park or urban greenspace.'),
            N'Eastern Gray Squirrel', @sqImg, 10, 0, N'Common', 1.0, 2, NULL, NULL, NULL, NULL, 0, NULL);
    SET @sq_i = @sq_i + 1;
END;

