-- ════════════════════════════════════════════════════════════════════
-- BADGE PROGRESS SYNC
-- Upserts PersonalBadges rows for sighting-related badges based on
-- the actual Sighting rows now in the database.
-- MERGE is idempotent — safe to re-run.
-- ════════════════════════════════════════════════════════════════════

DECLARE @uid  VARCHAR(450);
DECLARE @cnt  INT;
DECLARE @spec INT;
DECLARE @prog INT;

-- ── df6405d9-0dfb-415d-b77b-c779cecd000c ────────────────
SET @uid = 'df6405d9-0dfb-415d-b77b-c779cecd000c';
SELECT @cnt  = COUNT(*),
       @spec = COUNT(DISTINCT SpeciesName)
FROM   [dbo].[Sighting]
WHERE  UserId = @uid;

    -- FirstSighting (BadgeSteps = 1)
    SET @prog = IIF(@cnt >= 1, 1, @cnt);
    IF @prog > 0
    BEGIN
        MERGE [dbo].[PersonalBadges] AS tgt
        USING (SELECT @uid AS uid, 'B2C3D4E5-F6A7-4890-9B0C-1D2E3F4B5A6F' AS bid) AS src
            ON tgt.[User ID] = src.uid AND tgt.[Badge ID] = src.bid
        WHEN MATCHED THEN
            UPDATE SET [Badge Progress] = @prog,
                       BadgeEarned = IIF(@prog >= 1,
                           COALESCE(tgt.BadgeEarned, SYSDATETIMEOFFSET()), NULL)
        WHEN NOT MATCHED THEN
            INSERT (UserBadgeId, [User ID], [Badge ID], [Badge Progress], BadgeEarned)
            VALUES (NEWID(), @uid, 'B2C3D4E5-F6A7-4890-9B0C-1D2E3F4B5A6F', @prog,
                    IIF(@prog >= 1, SYSDATETIMEOFFSET(), NULL));
    END

    -- SightingNovice (BadgeSteps = 5)
    SET @prog = IIF(@cnt >= 5, 5, @cnt);
    IF @prog > 0
    BEGIN
        MERGE [dbo].[PersonalBadges] AS tgt
        USING (SELECT @uid AS uid, '27857EC5-189E-46E8-BE28-871123607F20' AS bid) AS src
            ON tgt.[User ID] = src.uid AND tgt.[Badge ID] = src.bid
        WHEN MATCHED THEN
            UPDATE SET [Badge Progress] = @prog,
                       BadgeEarned = IIF(@prog >= 5,
                           COALESCE(tgt.BadgeEarned, SYSDATETIMEOFFSET()), NULL)
        WHEN NOT MATCHED THEN
            INSERT (UserBadgeId, [User ID], [Badge ID], [Badge Progress], BadgeEarned)
            VALUES (NEWID(), @uid, '27857EC5-189E-46E8-BE28-871123607F20', @prog,
                    IIF(@prog >= 5, SYSDATETIMEOFFSET(), NULL));
    END

    -- SightingStudent (BadgeSteps = 25)
    SET @prog = IIF(@cnt >= 25, 25, @cnt);
    IF @prog > 0
    BEGIN
        MERGE [dbo].[PersonalBadges] AS tgt
        USING (SELECT @uid AS uid, '8436745D-C25B-44BF-A0E1-0C87E6122724' AS bid) AS src
            ON tgt.[User ID] = src.uid AND tgt.[Badge ID] = src.bid
        WHEN MATCHED THEN
            UPDATE SET [Badge Progress] = @prog,
                       BadgeEarned = IIF(@prog >= 25,
                           COALESCE(tgt.BadgeEarned, SYSDATETIMEOFFSET()), NULL)
        WHEN NOT MATCHED THEN
            INSERT (UserBadgeId, [User ID], [Badge ID], [Badge Progress], BadgeEarned)
            VALUES (NEWID(), @uid, '8436745D-C25B-44BF-A0E1-0C87E6122724', @prog,
                    IIF(@prog >= 25, SYSDATETIMEOFFSET(), NULL));
    END

    -- AnidexBeginner (BadgeSteps = 5)
